using System;
class Naval319Checks {
 static void Check(bool v,string why){if(!v)throw new Exception(why);}
 static void Main(){foreach(var ship in NavalShipDefinition.SteamChoices){Check(ship.ProjectileSpeed==NavalSmallCalibre.Speed&&ship.GunRange==500,"Common small-gun ballistics on every steam profile");Check(ship.GunRange<NavalMainBatteryMath.MaximumRange&&ship.GunRange<NavalCapitalLayout.Range,"Secondary range below both main batteries");}Check(Math.Abs(NavalShipDefinition.Novik.GunAxisHeight-1.42f)<.001,"Another half-metre lift");
 var s=NavalShipDefinition.Novik;foreach(float centre in new[]{-20.5f,20.5f})foreach(float side in new[]{-1f,1f}){var under=new NavalWalkPoint(side*3.6f/s.Scale,s.HoldFloor,centre/s.Scale);float floor;Check(!NavalStairTraffic.InPassage(under,s),"Under stairs is not on stairs");Check(NavalStairRecovery.Needed(under,under,s,out floor),"Under-flight escape required");var on=new NavalWalkPoint(under.X,(s.HoldFloor+s.WeatherDeck)*.5f,under.Z);Check(NavalStairTraffic.InPassage(on,s),"Real mid-flight sailor remains on stairs");Check(!NavalStairRecovery.Needed(on,on,s,out floor),"Do not eject legitimate stair traffic");var exit=NavalStairRecovery.Exit(under,under,s,s.HoldFloor,1,.8f);Check(Math.Abs(exit[0].X*s.Scale)>=5.5f,"Escape clears physical stair and full capsule");}
 Check(NavalTorpedoSalvoMath.Style(.1f,8)==0&&NavalTorpedoSalvoMath.Style(.5f,8)==1&&NavalTorpedoSalvoMath.Style(.9f,8)==2,"Three distinct salvo styles");Check(NavalTorpedoSalvoMath.Style(.9f,1)==0,"One round cannot form a fan");for(int style=0;style<3;style++){float near=NavalTorpedoSalvoMath.LaunchDistance(style,0),far=NavalTorpedoSalvoMath.LaunchDistance(style,1);Check(near<far&&near>NavalTorpedoMath.SafeRun&&far<NavalTorpedoMath.Range,"Variable launch bands inside motor limits");}Check(NavalTorpedoSalvoMath.FanHalfAngle(400,20)>0&&NavalTorpedoSalvoMath.FanHalfAngle(1000,20)<=3.5f,"Bounded fan width");
 Check(NavalShellEvasionMath.Threat(100,0,0,-50,9.81f,0,20),"Incoming arc triggers evasion");Check(!NavalShellEvasionMath.Threat(100,0,0,50,0,0,20),"Outgoing round not a threat");Check(!NavalShellEvasionMath.Threat(100,0,100,-50,9.81f,0,20),"Passing round not a threat");Console.WriteLine("PASS: unified secondary range, extra gun lift, four stair recoveries, varied salvos and incoming-shell prediction.");}
}
